CALCULATE(
    SUM(FactInternetSales[SalesAmount]),
    USERELATIONSHIP(FactInternetSales[ShipDateKey], DimDate[DateKey])
)

// Redesign: give ship-date sales its own always-active relationship
// instead of activating an inactive one at query time, e.g. via a
// dedicated FactInternetSalesByShipDate table or role-playing dimension
// already related to DimDate with no USERELATIONSHIP required:
Ship Date Sales =
